/** A paid answer ticket's deadline and what `result` says about it, a leaf module (XC-100): pure functions of
 * the stored job and the time, so the rules are tested without a database. `ticketResult` (answer-state.ts)
 * reads the job, expires it in D1 when `overdue` says so, and answers with `resultOf`. */

export const ANSWER_DISCLOSURE =
  "Generated by the owner's authorized AI proxy from owner-approved " +
  "publications; verify citations via get.";
export const ESTIMATE_SECONDS = 120;

/** How long the agent has to answer, and how long `result` waits past that before calling the ticket failed. */
export const DEADLINE_MS = 180_000;
export const RESULT_GRACE_MS = 60_000;
const NO_REFUND_NOTE = "No automated refund exists yet; contact the node owner.";
/** The reason an expired ticket is failed with. */
export const TIMED_OUT = "the agent did not finish in time";

export interface AnswerJob {
  ticket_id: string;
  question: string;
  price_usd: number;
  status: "running" | "complete" | "refused" | "failed";
  answer: string;
  cited_publication_ids: string;
  reason: string;
  model: string;
  input_tokens: number;
  output_tokens: number;
  cost_usd: number;
  tool_calls: number;
  duration_ms: number;
  created_at: string;
  updated_at: string;
}

/** Whether a ticket is still running past its deadline and grace, at `now` (ms since the epoch). A live
 * checkpoint still saves it; that check needs the database, so the caller makes it. */
export function overdue(job: Pick<AnswerJob, "status" | "created_at">, now: number): boolean {
  return job.status === "running" && now - Date.parse(job.created_at) > DEADLINE_MS + RESULT_GRACE_MS;
}

/** What `result` answers for a ticket in the state it is in. */
export function resultOf(
  job: Pick<AnswerJob, "status" | "answer" | "cited_publication_ids" | "reason">
): Record<string, unknown> {
  if (job.status === "running") return { status: "running", estimate_seconds: ESTIMATE_SECONDS };
  if (job.status === "complete") {
    return {
      status: "complete",
      answer: job.answer,
      cited_publication_ids: JSON.parse(job.cited_publication_ids) as string[],
      disclosure: ANSWER_DISCLOSURE
    };
  }
  return {
    status: job.status,
    reason: job.reason || (job.status === "refused" ? "no coverage" : "agent error"),
    note: NO_REFUND_NOTE
  };
}
